function validateAppState(value){validateState(value);if(!safeLearning(value.learning))throw Error('Invalid guided-learning backup.');if(!safeAssessments(value.assessments))throw Error('Invalid grading feedback in backup.');if(value.speakingAnswers!==undefined){if(!value.speakingAnswers||Array.isArray(value.speakingAnswers)||typeof value.speakingAnswers!=='object')throw Error('Invalid speaking answers.');for(const [key,a] of Object.entries(value.speakingAnswers))if(!/^p[123]-\d{1,3}$/.test(key)||!a||!['speaking_points','speaking_transcript'].includes(a.mode)||typeof a.text!=='string'||a.text.length>20000)throw Error('Invalid speaking answer.');}return value;}
const KEY='band-seven-lab-v1';
let state,storageAvailable=true,writeBlocked=false,recoveryRaw=null,recoveryWarning='',saveTimer=null;
try{const raw=localStorage.getItem(KEY),recovered=recoverSavedState(raw);state=recovered.state;writeBlocked=recovered.blocked;recoveryRaw=recovered.rawRecovery;recoveryWarning=recovered.warnings.join(' ');if(recovered.needsRecoveryBackup){try{localStorage.setItem(KEY+'-recovery',raw);}catch{writeBlocked=true;recoveryWarning+=' The original work is protected until you export a recovery copy.';}}storageAvailable=!writeBlocked;}catch{state=emptyState();storageAvailable=false;writeBlocked=true;recoveryWarning='Browser storage is unavailable. Keep this session open and export your work.';}
