const fmtDate=s=>new Date((s||dateKey()).slice(0,10)+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric'});
function storageWarning(){if(!storageAvailable&&!$('#storage-warning')){const el=document.createElement('section');el.id='storage-warning';el.className='notice warning';el.setAttribute('role','alert');el.innerHTML='<strong>'+esc(writeBlocked?'Original saved work is protected.':'This session is not saved to this browser.')+'</strong><p>'+esc(writeBlocked?'Automatic saving is paused to avoid overwriting recoverable work. Export your current session and the original recovery copy.':'Browser storage is unavailable or full. Your work remains in this tab; export it before leaving.')+'</p><div class="button-row">'+button('export-data','Export this session','outline small')+(recoveryRaw?button('export-recovery','Export original recovery copy','outline small'):'')+'</div>';$('#main')?.prepend(el);}}
function save(){clearTimeout(saveTimer);if(writeBlocked){storageAvailable=false;$('#save-status').textContent='Saving paused — original work protected';storageWarning();return false;}try{localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;$('#save-status').textContent='Saved on this browser';$('#storage-warning')?.remove();return true;}catch{storageAvailable=false;$('#save-status').textContent='Not saved — export this session';storageWarning();return false;}}
function queueSave(){clearTimeout(saveTimer);if(!writeBlocked)$('#save-status').textContent='Saving your changes…';saveTimer=setTimeout(save,400);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function link(url,label,cls=''){return `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;}
function button(action,label,cls='',data=''){return `<button type="button" class="button ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function head(kicker,title,description){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><span class="pill">Academic · target 9 in every skill</span></div>`;}
function empty(title,text,href,label){return `<div class="empty"><strong>${title}</strong>${text}${href?`<br><a class="button small" href="#${href}">${label}</a>`:''}</div>`;}
function prompt(){return prompts.find(p=>p.id===state.selectedPrompt)||prompts[0];}
function draft(){const p=prompt();if(!state.drafts[p.id])state.drafts[p.id]={text:'',checks:checks[p.type].map(()=>false)};return state.drafts[p.id];}
function readTimer(){const t=state.timer;return t?`${t.label} · ${clock(secondsLeft(t))}`:'';}
function timerControls(kind,seconds,label){const mine=state.timer?.kind===kind;return `<div class="timer-box"><div><div class="prompt-meta">${esc(label)}</div><div class="timer-display" data-timer-value="${kind}">${mine?clock(secondsLeft(state.timer)):clock(seconds)}</div></div><div class="button-row">${button('timer-start',mine&&state.timer.running?'Pause':'Start','',`data-kind="${kind}" data-seconds="${seconds}" data-label="${esc(label)}"`)}${button('timer-reset','Reset','subtle',`data-kind="${kind}" data-seconds="${seconds}" data-label="${esc(label)}"`)}</div></div>`;}
function chartHtml(attempts){const list=attempts.filter(a=>a.listening!==null||a.reading!==null).slice(-6);if(!list.length)return empty('Your baseline goes here','Record a fresh full test to start a useful comparison.','scores','Add a result');return `<div class="legend"><span><i></i>Listening /40</span><span><i class="reading"></i>Academic Reading /40</span></div><div class="chart" role="img" aria-label="Fresh practice results: ${esc(list.map(a=>`${a.source}: listening ${a.listening??'unrecorded'}, reading ${a.reading??'unrecorded'}`).join('; '))}">${list.map(a=>`<div class="chart-group">${a.listening!==null?`<div class="chart-bar" style="height:${a.listening/40*100}%"><span>${a.listening}</span></div>`:''}${a.reading!==null?`<div class="chart-bar reading" style="height:${a.reading/40*100}%"><span>${a.reading}</span></div>`:''}</div>`).join('')}</div><div class="chart-labels">${list.map(a=>`<span>${fmtDate(a.date)}</span>`).join('')}</div>`;}
function drillPage(){return renderDrill({active:activeDrill,drills,state,answers:drillAnswers,result:drillResult,head,button,esc,timerControls,activeLesson:matchingLesson('drill',activeDrill?.id)});}
function scores(){const fresh=freshMocks(state),complete=fresh.filter(a=>a.bands.every(b=>b!==null)),latest=complete.at(-1),value=latest?overall(latest.bands):null,met=latest&&latest.bands.every(b=>b>=9);return head('MEASURE THE RIGHT THINGS','Your mock results.','Log complete tests from official sources. Keep fresh tests, repeats and untimed attempts separate.')+`<div class="grid-even"><section class="card"><div class="card-head"><h2>Record a practice test</h2><span class="tag">FULL TESTS ONLY</span></div><p class="text-small muted">Use the test’s own answer key and band conversion. Raw marks alone do not produce an exact band. Leave unknown scores blank.</p><div class="button-row" style="margin:16px 0">${link(sources[1][1],'Official samples','button outline small')}${link(sources[2][1],'IELTS Ready','button outline small')}</div><form id="mock-form"><div class="form-row"><label for="mock-source">Test source and identifier</label><input id="mock-source" name="source" required maxlength="300" placeholder="e.g. IELTS Ready — Mock 1"></div><div class="field-grid form-row"><div><label for="mock-date">Date completed</label><input id="mock-date" type="date" name="date" value="${dateKey()}" required></div><div><label for="mock-mode">Attempt type</label><select id="mock-mode" name="mode"><option value="fresh">Fresh · first time seeing it</option><option value="repeat">Repeated test</option><option value="untimed">Untimed / paused / with help</option></select></div></div><div class="field-grid form-row"><div><label for="mock-l">Listening /40</label><input id="mock-l" type="number" name="listening" min="0" max="40" step="1" placeholder="Optional"></div><div><label for="mock-r">Academic Reading /40</label><input id="mock-r" type="number" name="reading" min="0" max="40" step="1" placeholder="Optional"></div></div><h3 style="margin-top:22px">Section bands, when available</h3><p class="text-small muted">L/R: enter the source’s reported bands. W/S: use external assessment or a clearly labelled estimate.</p><div class="field-grid four form-row">${['Listening','Reading','Writing','Speaking'].map((s,i)=>`<div><label for="band-${i}">${s}</label><input id="band-${i}" name="band${i}" type="number" min="0" max="9" step="0.5" placeholder="—"></div>`).join('')}</div><div class="form-row"><label for="mock-provenance">Where did the Writing/Speaking bands come from?</label><select id="mock-provenance" name="provenance"><option value="unknown">Not assessed / unknown</option><option value="teacher">Teacher assessment (practice)</option><option value="ai">AI estimate (provisional)</option><option value="self">My own estimate (provisional)</option><option value="official">Official IELTS test result</option></select></div><button class="button">Save test result</button><div id="mock-error" class="form-error" role="alert"></div></form></section><div><section class="card"><div class="card-head"><h2>Latest complete fresh profile</h2><span class="tag">${latest?esc(latest.provenance):'NO PROFILE YET'}</span></div>${latest?`<div class="score-big">${value.toFixed(1)}<small> overall</small></div><div class="profile">${latest.bands.map((b,i)=>`<div><small>${['LISTENING','READING','WRITING','SPEAKING'][i]}</small><strong>${b.toFixed(1)}</strong></div>`).join('')}</div><p class="text-small muted">${esc(latest.source)} · ${fmtDate(latest.date)} · W/S: ${esc(latest.provenance)}.<br>${met?'This recorded profile meets your configured target. Check it again with a fresh test.':'This recorded profile does not yet meet your configured target.'}</p><div class="notice">${latest.provenance==='official'?'A reported official result.':'Practice evidence, not an official result or a guarantee. Self/AI/teacher estimates introduce uncertainty.'} Overall is calculated only from four bands recorded in this same attempt.</div>`:empty('Not enough evidence yet','Record all four section bands in one fresh attempt to see a complete profile. No missing skill is assumed.')}</section><section class="card"><div class="card-head"><h2>Fresh raw-score trend</h2></div>${chartHtml(fresh)}<div class="notice">Published Band 7 benchmark: roughly 30/40 in Listening and Academic Reading. Around 35/40 is the Band 8 benchmark. Exact cutoffs vary. Aim beyond the minimum.</div>${link(sources[0][1],'How IELTS scoring works','text-small')}</section></div></div><section class="card" style="margin-top:22px"><div class="card-head"><h2>Every attempt, honestly labelled</h2><span class="tag">${state.mockAttempts.length} RECORDS</span></div>${state.mockAttempts.length?`<div class="scroll-table"><table><thead><tr><th>Test</th><th>Type</th><th>L /40</th><th>R /40</th><th>Band profile L/R/W/S</th><th></th></tr></thead><tbody>${state.mockAttempts.slice().reverse().map(a=>`<tr><td>${esc(a.source)}<br><small class="muted">${fmtDate(a.date)}</small></td><td><span class="tag ${a.mode==='fresh'?'':'orange'}">${a.mode}</span></td><td title="${esc(rawGuide(a.listening,'Listening'))}">${a.listening??'—'}</td><td title="${esc(rawGuide(a.reading,'Reading'))}">${a.reading??'—'}</td><td>${a.bands.map(b=>b??'—').join(' / ')}<br><small class="muted">W/S: ${esc(a.provenance)}</small></td><td>${button('delete-mock','Delete','subtle small',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your honest starting point','One fresh baseline is more useful than a guessed score.')}</section>`;}
function mistakes(){const sorted=state.mistakes.slice().sort((a,b)=>a.due.localeCompare(b.due));return head('MAKE ERRORS USEFUL','Your mistake notebook.','Recall the answer before revealing it. Review again tomorrow, then space successful recalls further apart.')+`<div class="grid-2"><section><div class="card"><h2>Add something worth remembering</h2><form id="mistake-form"><div class="field-grid form-row"><div><label for="mistake-skill">Skill</label><select id="mistake-skill" name="skill">${['Listening','Reading','Writing','Speaking','Language'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label for="mistake-tag">Error type</label><input id="mistake-tag" name="tag" maxlength="100" placeholder="e.g. distractor / overview / articles" required></div></div><div class="form-row"><label for="mistake-problem">Question or mistake to recall</label><textarea id="mistake-problem" name="problem" rows="2" maxlength="2000" required></textarea></div><div class="form-row"><label for="mistake-fix">Correction, evidence and rule</label><textarea id="mistake-fix" name="fix" rows="3" maxlength="5000" required></textarea></div><button class="button">Add to tomorrow’s review</button></form></div>${sorted.length?sorted.map(m=>`<article class="mistake-card"><div><span class="tag">${esc(m.skill)}</span><span class="tag">${esc(m.tag)}</span><span class="tag ${m.due<=dateKey()?'orange':''}">${m.due<=dateKey()?'DUE NOW':'REVIEW '+fmtDate(m.due)}</span></div><h3>${esc(m.problem)}</h3>${reviewRevealed.has(m.id)?`<div class="mistake-answer">${esc(m.fix)}</div><p class="text-small muted">Could you explain the correction before seeing it?</p><div class="button-row">${button('review-good','Recalled correctly','',`data-id="${m.id}"`)}${button('review-again','Needs another try','outline',`data-id="${m.id}"`)}${button('delete-mistake','Delete','subtle small',`data-id="${m.id}"`)}</div>`:button('reveal-mistake','Reveal correction','outline small',`data-id="${m.id}"`)}</article>`).join(''):empty('Your errors can teach you','Missed drill questions arrive here automatically. Add errors from official tests and your own writing, too.')}</section><aside><div class="card"><div class="eyebrow">WHY THIS LOOP EXISTS</div><h2 style="margin-top:10px">Retrieve, then check.</h2><p class="text-small muted">Try to explain the answer from memory. Then reveal the correction and compare. Feedback helps prevent a wrong answer from becoming a habit.</p><p class="text-small muted">A successful recall schedules a later review. A miss comes back tomorrow. The intervals are a practical study schedule, not an IELTS score prediction.</p><div class="rule"></div><h3>Measure transfer too</h3><p class="text-small muted">Remembering an old answer is useful. Improving on an unseen official test is stronger evidence that your skill is changing.</p></div></aside></div>`;}
function videosPage(){const list=videos.filter(v=>(videoFilter==='All'||v.skill===videoFilter)&&`${v.title} ${v.topic} ${v.channel}`.toLowerCase().includes(videoSearch.toLowerCase())),practised=videos.filter(v=>state.videos[v.id]?.practised).length;return head('WATCH ONE. DO SOMETHING WITH IT.','Your video library.',`${videos.length} researched YouTube lessons, grouped by skill. Each one has a practice action so the learning continues after the video.`)+`<div class="notice">Start with the crash course and your weakest skill. The longer courses are reference libraries—use relevant chapters, rather than spending the week watching everything. Titles mentioning bands are the creators’ titles, not promises.</div><div class="field-grid"><div class="filter-row" role="group" aria-label="Filter videos by skill">${['All','Orientation','Listening','Reading','Writing','Speaking'].map(f=>`<button class="filter ${f===videoFilter?'active':''}" data-action="video-filter" data-filter="${f}" aria-pressed="${f===videoFilter}">${f}</button>`).join('')}</div><div style="align-self:center"><label class="sr-only" for="video-search">Search videos</label><input id="video-search" type="search" placeholder="Search topics or creators…" value="${esc(videoSearch)}"></div></div><p class="text-small muted">${list.length} lessons shown · ${practised} follow-up exercises marked complete · researched 14 October 2026</p><div class="video-grid">${list.map(v=>{const prog=state.videos[v.id]||{watched:false,practised:false};return `<article class="video-card"><div class="video-top"><span class="skill-label">${esc(v.skill)}<br><small>PREP LESSON</small></span>${link(v.url,'▶','play')}</div><div class="video-body"><div><span class="tag">${esc(v.priority)}</span><span class="tag">${esc(v.topic)}</span></div><h3>${esc(v.title)}</h3><div class="channel">${esc(v.channel)} · YouTube</div><div class="video-exercise"><strong>After watching</strong><br>${esc(v.exercise)}</div><label class="check-item"><input type="checkbox" data-video="${v.id}" data-status="watched" ${prog.watched?'checked':''}><span>I watched the relevant lesson</span></label><label class="check-item"><input type="checkbox" data-video="${v.id}" data-status="practised" ${prog.practised?'checked':''}><span>I completed the follow-up exercise</span></label>${link(v.url,'Watch on YouTube','button outline small')}</div></article>`;}).join('')}</div>${!list.length?empty('No matching lessons','Try a different topic or clear the search.'):''}`;}
function settings(){return head('YOUR PLAN. YOUR DATA.','Make it work for you.','Set your dates, keep a backup, and see the sources behind the study tools.')+`<div class="grid-even"><div><section class="card"><h2>Your study settings</h2><form id="settings-form"><div class="field-grid form-row"><div><label for="settings-start">Preparation starts</label><input id="settings-start" name="start" type="date" value="${state.settings.start}" required></div><div><label for="settings-exam">Test date</label><input id="settings-exam" name="exam" type="date" value="${state.settings.exam}" required></div></div><div class="field-grid form-row"><div><label for="settings-hours">Focused study hours/day</label><input id="settings-hours" name="hours" type="number" value="${state.settings.hours}" min="1" max="8" step="0.5" required></div><div><label for="settings-min">Minimum in each section, if required</label><select id="settings-min" name="minimum"><option value="">No section minimum entered</option>${[5,5.5,6,6.5,7,7.5,8,8.5,9].map(x=>`<option value="${x}" ${state.settings.minimum===x?'selected':''}>${x.toFixed(1)}</option>`).join('')}</select></div></div><button class="button">Save settings</button><div id="settings-error" class="form-error" role="alert"></div></form><p class="text-small muted">Target: Band 9 in Listening, Reading, Writing and Speaking. Keep your university’s actual requirement separate from this training goal. Keep a normal sleep schedule; more exhausted hours do not make better evidence.</p></section><section class="card"><h2>Your work stays with you</h2><p class="text-small muted">Drafts, notes, scores and progress are saved in this browser on this device. They do not automatically sync between devices. Clearing browser data can erase them.</p><p class="text-small muted">Export a backup regularly. Speaking audio stays in the current session only—download recordings separately.</p><div class="button-row">${button('export-data','Export backup')}${button('choose-import','Import backup','outline')}${button('download-summary','Download progress report','subtle')}</div><div class="button-row" style="margin-top:10px">${button('backup-text','Copy/paste backup','outline small')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="rule"></div>${button('reset-data','Reset all saved work','outline small')}<div class="notice ${storageAvailable?'':'warning'}">${storageAvailable?'Browser storage is available. A backup gives you a portable copy.':'Storage is currently unavailable or a saved record could not be loaded. Export this session before leaving. Existing stored data has not been intentionally deleted.'}</div></section></div><section class="card"><div class="eyebrow">RESEARCH & LIMITS</div><h2 style="margin-top:10px">What the app measures</h2><p class="research-note">Full-test raw scores come from the answer keys you use. Overall band arithmetic uses only four section bands from a single recorded attempt. Writing checklists, word counts and timer use do not establish a band.</p><p class="research-note">The original mini drills measure item accuracy. Repeats are labelled. The mistake notebook uses recall, corrective feedback and spaced revisits. These are research-informed study tools; this particular app has not been validated as an IELTS intervention.</p><p class="research-note">AI feedback uses Google Gemini through the private companion grader. Set up your Google AI Studio key once in that private window; it is not part of this public page or your backup. Your existing browser drafts and progress stay here. Free-tier quotas apply, with no automatic paid fallback. Google may use unpaid-tier submissions and responses to improve its products; see its data terms.</p><p class="research-note">Bands are provisional estimates for a Writing task or the speech audible in a recorded sample, not official results. Talking points receive coaching without band scores. Transcripts cannot establish pronunciation, spoken fluency or an overall Speaking band; check any recognised transcript against what you actually said.</p><p class="research-note">${link('https://ai.google.dev/gemini-api/terms','Google data terms')} · ${link('https://ai.google.dev/gemini-api/docs/pricing','Gemini free-tier details')}</p><div class="rule"></div><div class="sources-list">${sources.map(s=>`${link(s[1],s[0])}<p>${esc(s[2])}</p>`).join('')}</div><p class="text-small muted">Sources and video links researched 14 October 2026. Free resources can have optional paid products; sign-up may be required.</p></section></div>`;}
const mainNav=[['today','01','Your next session'],['learn','02','Learn & practise'],['progress','03','Your progress'],['more','04','All tools']];
function render(){ensureLearning(state);const raw=location.hash.slice(1)||'today';route=raw.startsWith('lesson-')?'lesson':raw;if(route==='lesson'&&lessons.some(l=>l.id===raw.slice(7)))ensureLearning(state).current=raw.slice(7);if(![...nav.map(n=>n[0]),'learn','progress','more','lesson','grading','band9'].includes(route))route='today';const group=['today','learn','progress','more'].includes(route)?route:route==='lesson'||['writing','speaking','drills'].includes(route)?'learn':route==='scores'?'progress':'more';$('#navigation').innerHTML=mainNav.map(n=>`<a href="#${n[0]}" class="nav-item ${n[0]===group?'active':''}" ${n[0]===group?'aria-current="page"':''}><span class="nav-num">${n[1]}</span>${n[2]}</a>`).join('');try{let view=route==='lesson'?learningUI.lesson(raw.slice(7)):({today:learningUI.today,learn:learningUI.learn,progress:learningUI.progress,more:learningUI.more,grading:studio.hub,band9:studio.band9,writing,speaking,drills:drillPage,scores,mistakes,videos:videosPage,settings}[route])();if(route==='today')view=studio.quickStart()+view;if(route==='progress')view+=studio.recent();const banner=(route==='writing'&&matchingLesson('writing',prompt().id))||(route==='speaking'&&matchingLesson('speaking',String(state.selectedCue)))||(route==='drills'&&matchingLesson('drill',activeDrill?.id));$('#main').innerHTML=(banner?learningUI.banner():'')+view;storageWarning();}catch(e){$('#main').innerHTML=empty('This view could not load','Your saved work is still in this browser. Try reloading or open Settings.','settings','Open Settings');console.error(e);}const title=({grading:'AI feedback',band9:'Your Band 9 plan'}[route])||mainNav.find(n=>n[0]===route)?.[2]||nav.find(n=>n[0]===route)?.[2]||'Guided session';document.title=`${title} · Band Nine`;updateTimer();if(!storageAvailable)$('#save-status').textContent='Storage issue — export a backup';}
function matchingLesson(type,id){const l=lessons.find(l=>l.id===ensureLearning(state).practice);return l?.practice.type===type&&String(l.practice.id)===String(id)?l:null;}
function reviewChecks(p){return getWritingMinimum(p)===60?['My paragraph has one clear main claim.','I explained why or how that claim holds.','I added a relevant example or consequence.','Each sentence develops the same idea.','My vocabulary is precise and appropriate.','I checked grammar and punctuation.']:checks[p.type];}
function getWritingMinimum(p){return matchingLesson('writing',p.id)?.id==='writing-paragraph-development'?60:p.type===1?150:250;}
function writing(){let html=studio.writing();if(writingReport?.promptId===prompt().id&&writingReport.text===draft().text){const r=writingReport.report;html+=`<section class="card revision-report" id="writing-report"><span class="eyebrow">OFFLINE LANGUAGE CHECKS · NOT AN AI GRADE</span><h2>Quick patterns to inspect</h2>${r.findings.map(f=>`<div class="revision-item"><h3>${esc(f.title)}</h3>${f.quote?`<blockquote>${esc(f.quote)}</blockquote>`:''}<p>${esc(f.detail)}</p></div>`).join('')}<ol>${r.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></section>`;}return html;}
function speaking(){return studio.speaking();}
function speakingContext(){const lesson=matchingLesson('speaking',String(state.selectedCue)),part=lesson?.id==='speaking-part1'?1:lesson?.id==='speaking-part3'?3:questionPart;if(part===2){const cue=cues[state.selectedCue];return {part,promptId:`p2-${state.selectedCue}`,title:'Describe '+cue[0],points:cue.slice(1),prompt:`IELTS Speaking Part 2. Describe ${cue[0]}. You should say: ${cue.slice(1).join('; ')}.`};}const questions=part===1?part1:part3,index=questionIndex%questions.length,title=questions[index];return {part,promptId:`p${part}-${index}`,title,prompt:`IELTS Speaking Part ${part}: ${title}`};}
function speakingAnswer(){if(!state.speakingAnswers)state.speakingAnswers={};const key=speakingContext().promptId;if(!state.speakingAnswers[key])state.speakingAnswers[key]={mode:'speaking_points',text:''};return state.speakingAnswers[key];}
function recorderHtml(){return `<div class="button-row">${recordingPending?button('record-start','Waiting for microphone…','outline','disabled'):recording?button('record-stop','<span class="recording-dot"></span>Stop recording','danger'):button('record-start','● Start recording','outline')}${audioBlob?button('submit-recording',gradeJob?'Grading in progress…':'Grade this recording','',gradeJob?'disabled aria-disabled="true"':'')+button('audio-download','Download recording','subtle small'):''}</div><p class="text-small muted">${recording?'Recording now. It will stop after two minutes.':audioBlob?`Available in this tab: ${esc(audioContext?.title||'your answer')}. ${audioContext?.duration?Math.round(audioContext.duration)+' seconds.':'Uploaded audio.'}`:'Recording is optional. Your audio stays in this tab until you explicitly submit it.'}</p><label for="recording-upload" class="text-small">Or choose an audio file (up to 2 minutes, 8 MB)</label><input type="file" id="recording-upload" accept="audio/*,.webm,.m4a,.mp3,.wav" ${recording?'disabled':''}>${audioUrl?`<audio controls src="${esc(audioUrl)}" aria-label="Your speaking practice recording"></audio>`:''}`;}
async function beginRecording(){if(recording||recordingPending)return;if(gradeJob){toast('Wait for the current grading request or cancel it first.');return;}if(!navigator.mediaDevices?.getUserMedia||!globalThis.MediaRecorder){toast('This browser cannot record. Type a transcript or record on your phone.');return;}const requestId=++recordRequestId;recordingPending=true;let pendingStream;if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();try{const context={...speakingContext(),cueIndex:state.selectedCue,startedAt:Date.now()},stream=await navigator.mediaDevices.getUserMedia({audio:true});pendingStream=stream;if(requestId!==recordRequestId||route!=='speaking'){stream.getTracks().forEach(t=>t.stop());return;}const chunks=[],r=new MediaRecorder(stream);r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};r.onstop=()=>{clearTimeout(recordingTimeout);stream.getTracks().forEach(t=>t.stop());if(audioUrl)URL.revokeObjectURL(audioUrl);audioBlob=new Blob(chunks,{type:r.mimeType||'audio/webm'});audioUrl=URL.createObjectURL(audioBlob);audioContext={...context,duration:(Date.now()-context.startedAt)/1000};audioCue=context.cueIndex;recording=null;if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();};r.start();context.startedAt=Date.now();recording=r;recordingTimeout=setTimeout(()=>{if(r.state==='recording')r.stop();},120000);if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();}catch{pendingStream?.getTracks().forEach(t=>t.stop());if(requestId===recordRequestId)toast('Microphone access was not granted. You can submit talking points or a transcript instead.');}finally{if(requestId===recordRequestId){recordingPending=false;if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();}}}
function markDraftChanged(){const feedback=$('#assessment-feedback');if(feedback&&!feedback.querySelector('[data-draft-changed]')){const note=document.createElement('div');note.className='notice warning';note.dataset.draftChanged='true';note.textContent='Your answer has changed. The feedback below remains attached to the saved submission; submit again to assess your revision.';feedback.prepend(note);}}
function cancelGrading(){gradeGeneration++;gradeJob?.controller.abort();gradeJob=null;gradeError=null;lastFailed=null;}
function connectGrader(){if(!connectionPromise){const portal=openGeminiPortal({onConnection:status=>{graderConnected=status.configured;}});connectionPromise=portal.ready.then(status=>{if(status.error)throw status.error;graderConnected=status.configured;portal.dispose?.();return status;}).finally(()=>{connectionPromise=null;});}return connectionPromise;}
async function submitWriting(){try{if(gradeJob)return;const p=prompt(),d=draft();if(wordCount(d.text)<10){toast('Write at least a short attempt before submitting.');return;}const scope=getWritingMinimum(p)===60?'writing_fragment':'writing_task',latest=(state.assessments||[]).filter(r=>r.submission.promptId===p.id&&r.submission.scope===scope).at(-1);if(latest?.submission.text===d.text){toast('This exact answer already has feedback. Revise it before submitting again.');$('#assessment-feedback')?.scrollIntoView({behavior:'smooth'});return;}const submission=createSubmission({scope,promptId:p.id,taskType:p.type,prompt:p.title+'\n'+p.text+(p.table?'\nData: '+JSON.stringify(p.table):''),text:d.text});if(!state.writingHistory.some(h=>h.promptId===p.id&&h.text===d.text))state.writingHistory.push({id:submission.id,promptId:p.id,text:d.text,checks:[...d.checks],date:submission.createdAt});save();await runGrading({submission});}catch(err){toast(err.message);}}
async function submitSpeaking(){try{const context=speakingContext(),answer=speakingAnswer();if(wordCount(answer.text)<5){toast('Add a few meaningful talking points or your spoken answer first.');return;}await runGrading({submission:createSubmission({scope:answer.mode,promptId:context.promptId,prompt:context.prompt,text:answer.text})});}catch(err){toast(err.message);}}
async function submitRecording(){if(!audioBlob||!audioContext){toast('Record an answer first.');return;}if(recording){toast('Stop recording before submitting.');return;}await runGrading({blob:audioBlob,context:{...audioContext},originalAnswer:{...(state.speakingAnswers?.[audioContext.promptId]||{mode:'speaking_points',text:''})}});}
async function runGrading(request){if(gradeJob){toast('A submission is already being graded.');return;}const generation=++gradeGeneration,controller=new AbortController();gradeJob={controller,stage:'Opening your private Gemini grader…'};gradeError=null;lastFailed=request;const current=()=>generation===gradeGeneration&&!controller.signal.aborted;const stage=message=>{if(!current())return;gradeJob.stage=message;const el=$('#grading-stage');if(el)el.textContent=message;};try{const portal=openGeminiPortal({signal:controller.signal,onStage:stage,onConnection:status=>{graderConnected=status.configured;}});render();let submission=request.submission;if(request.blob){stage('Preparing the audio sample in this browser…');const audio=await recordingToWav(request.blob);if(!current())return;submission=createSubmission({scope:'speaking_audio',promptId:request.context.promptId,prompt:request.context.prompt,text:'',audio});request={submission};lastFailed=request;}stage('Waiting for the private Gemini grader…');const report=await portal.grade(submission);if(!current())return;saveAssessment(state,submission,report);if(submission.scope.startsWith('writing_')&&wordCount(submission.text)>=(submission.scope==='writing_fragment'?60:submission.taskType===1?150:250))finishLesson(state,lessons,'writing',submission.promptId);gradeJob=null;gradeError=null;lastFailed=null;const persisted=save();render();($('#assessment-feedback')||$('.audio-assessment-feedback'))?.scrollIntoView({behavior:'smooth',block:'start'});toast(persisted?'Feedback saved. Choose one priority and revise.':'Feedback is available in this tab. Storage is full — export a backup now.');}catch(err){if(!current())return;controller.abort();gradeJob=null;const code=err.code||'network';if(['invalid_key','sign_in_required','setup_required','service_unconfigured'].includes(code))graderConnected=false;gradeError={message:err.message||'Gemini did not finish. Your answer remains available to retry.',code,retryAfter:err.retryAfter||null};lastFailed=request;render();}}
function openDrill(id){activeDrill=drills.find(d=>d.id===id);if(!activeDrill)return;drillAnswers={};drillResult=null;drillPlays=0;drillStarted=Date.now();if(location.hash==='#drills')render();else location.hash='drills';window.scrollTo(0,0);}
function startTimer(kind,seconds,label){if(state.timer?.kind===kind){const left=secondsLeft(state.timer);state.timer=state.timer.running?{...state.timer,running:false,remaining:left}:{...state.timer,running:true,end:Date.now()+(left||seconds)*1000,remaining:left||seconds};}else{if(state.timer?.running&&secondsLeft(state.timer)>0&&!confirm('Replace the running timer with this practice timer?'))return;state.timer={kind,label,running:true,end:Date.now()+seconds*1000,remaining:seconds};}save();render();}
function updateTimer(){const t=state.timer,chip=$('#global-timer');chip.hidden=!t;if(!t)return;const left=secondsLeft(t);chip.textContent=readTimer();$$('[data-timer-value]').forEach(el=>{if(el.dataset.timerValue===t.kind)el.textContent=clock(left);});if(t.kind.startsWith('speaking')&&$('#speaking-clock')){$('#speaking-clock').textContent=clock(left);$('#speaking-phase').textContent=t.label;}if(t.running&&left===0){t.running=false;t.remaining=0;save();toast(`${t.label}: time is up. Save your attempt, then review.`);if((route==='writing'||route==='drills')&&!recording)render();}}
function download(filename,content,type='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.style.display='none';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function feedbackText(){const p=prompt();if(getWritingMinimum(p)===60)return `IELTS Academic paragraph practice. The full essay prompt is context: ${p.text}\n\nMy body paragraph:\n${draft().text}\n\nGive feedback on this paragraph's main claim, explanation, example, coherence and language. Quote actual issues and suggest revisions. This is not a complete essay, so do not assign a full Writing band.`;return `IELTS Academic practice — ${p.title}\nOriginal prompt: ${p.text}\n${p.table?JSON.stringify(p.table,null,2)+'\n':''}\nMy unedited answer (${wordCount(draft().text)} words):\n${draft().text}\n\nPlease assess this against current public IELTS Writing criteria. Give a cautious estimated band range with uncertainty; identify three highest-impact issues with specific examples, explain corrections, and give a short drill. Do not infer a band from word count alone. Let me revise before giving a full rewrite.`;}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Copied. Paste it into this chat or share it with your teacher.');}catch{showModal('Copy your answer',`<textarea rows="14" readonly>${esc(s)}</textarea>`);}}
function showModal(title,html){$('#modal-body').innerHTML=`<h2>${esc(title)}</h2>${html}`;$('#modal').showModal();}
function addMistake(m){const exists=state.mistakes.find(x=>x.origin===m.origin&&m.origin);if(exists){Object.assign(exists,{fix:m.fix,level:0,due:addDays(dateKey(),1)});reviewRevealed.delete(exists.id);}else state.mistakes.push({id:uid(),skill:m.skill,tag:m.tag,problem:m.problem,fix:m.fix,origin:m.origin||null,due:addDays(dateKey(),1),level:0});}
document.addEventListener('click',async e=>{if(e.target.closest('a[href="#writing"],a[href="#speaking"],a[href="#drills"]')){ensureLearning(state).practice=null;save();}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){
case 'connect-grader':try{b.disabled=true;await connectGrader();gradeError=null;render();toast('Private Gemini grader connected. Submit your answer when ready.');}catch(err){b.disabled=false;toast(err.message||'Connection did not finish. Click Connect grader again.');}break;
case 'submit-writing':await submitWriting();break;
case 'submit-speaking':await submitSpeaking();break;
case 'submit-recording':await submitRecording();break;
case 'cancel-grading':cancelGrading();render();toast('Request cancelled. Work already sent may use your AI allowance.');break;
case 'retry-grading':if(lastFailed)await runGrading(lastFailed);break;
case 'copy-grading-request':{const submission=lastFailed?.submission;if(!submission){toast('Submit an answer first. Its exact version will be available here if the connection fails.');break;}showModal('Continue in the private grader','<p>Copy this saved request, open the private grader, and use its manual handoff section. It contains your submitted answer, not an API key.</p><textarea id="manual-grade-request" rows="8" readonly>'+esc(JSON.stringify(submission))+'</textarea><div class="button-row">'+button('copy-manual-request','Copy request')+'<a class="button outline" href="https://ielts-gemini-grader-dion.hf5r5r9j8h.chatgpt.site/" target="_blank" rel="noopener noreferrer">Open private grader ↗</a></div>');break;}
case 'copy-manual-request':try{await navigator.clipboard.writeText($('#manual-grade-request').value);toast('Request copied. Paste it in the private grader.');}catch{toast('Select and copy the request text above.');}break;
case 'import-grade':showModal('Bring back your Gemini feedback','<p>Paste the returned result from your private grader. The report will stay linked to its submitted answer.</p><textarea id="manual-grade-result" rows="8" maxlength="8000000"></textarea><div class="button-row">'+button('save-imported-grade','Import feedback')+'</div>');break;
case 'save-imported-grade':try{const record=JSON.parse($('#manual-grade-result').value);if(!safeAssessments([record]))throw Error('The returned submission or feedback is invalid.');const submission=Object.fromEntries(['id','scope','promptId','prompt','text','taskType','target','createdAt'].map(key=>[key,record.submission[key]]));if(record.submission.audio)submission.audio={format:record.submission.audio.format,duration:record.submission.audio.duration};const report=validateAssessment(record.assessment,submission);cancelGrading();report.limitations=[...new Set(['Imported manually; this app did not verify the live connection for this report.',...report.limitations])].slice(0,12);const history=ensureAssessments(state);if(!history.some(x=>x.assessment.id===report.id)){history.push({submission,assessment:report});if(history.length>200)history.shift();}const persisted=save();$('#modal').close();render();toast(persisted?'Imported feedback saved.':'Feedback imported in this tab. Export a backup before leaving.');}catch(err){toast('Import did not finish: '+err.message);}break;
case 'view-assessment':{const r=(state.assessments||[]).find(r=>r.assessment.id===b.dataset.id);if(r)showModal('Your saved feedback',renderAssessment(r.assessment,{submission:r.submission}));break;}
case 'advanced-practice':{const task=bandNineSessions.find(t=>t.id===b.dataset.id);if(!task)break;ensureLearning(state).practice=null;if(task.promptId)state.selectedPrompt=task.promptId;if(task.mode)questionPart=task.mode==='part3'?3:2;save();location.hash=task.href.slice(1);break;}
case 'open-lesson':{const l=lessons.find(l=>l.id===b.dataset.id);if(!l)break;ensureLearning(state).current=l.id;lessonRecord(state,l.id);save();if(location.hash==='#lesson-'+l.id)render();else location.hash='lesson-'+l.id;break;}
case 'course-filter':courseFilter=b.dataset.filter;render();break;
case 'lesson-step':{const r=lessonRecord(state,b.dataset.id),step=Number(b.dataset.step);if(step===2&&!r.submitted){toast('Try the quick check first.');break;}r.step=step;save();render();window.scrollTo(0,0);break;}
case 'lesson-practice':{const l=lessons.find(l=>l.id===b.dataset.id);if(!l)break;ensureLearning(state).practice=l.id;ensureLearning(state).current=l.id;save();if(l.practice.type==='drill')openDrill(l.practice.id);else if(l.practice.type==='writing'){state.selectedPrompt=l.practice.id;writingReport=null;save();location.hash='writing';}else{state.selectedCue=Number(l.practice.id);questionIndex=0;questionPart=l.id==='speaking-part3'?3:1;save();location.hash='speaking';}break;}
case 'review-writing':{const p=prompt(),text=draft().text;if(wordCount(text)<10){toast('Write a short attempt first, then ask for a revision plan.');break;}const report=writingReview(text,p.type);if(getWritingMinimum(p)===60){report.minimum=60;report.findings=report.findings.filter(f=>!f.title.startsWith('Develop the answer')&&f.title!=='Make the organisation visible');if(report.words<60)report.findings.unshift({title:'Develop this paragraph to about 60–100 words',detail:'Explain the main claim and add a relevant example or consequence.',quote:''});report.questions=['Underline the one main claim.','Which sentence explains why or how it happens?','Which example or consequence makes the explanation concrete?'];}writingReport={promptId:p.id,text,report};render();$('#writing-report')?.scrollIntoView({behavior:'smooth'});break;}
case 'show-model':{const p=prompt(),model=writingModels[p.id]||writingModels[p.type===1?'table-1':'essay-1'];showModal('Worked example: '+model.title,`<p class="text-small muted">Original teaching example, unscored. Study how the answer is built, then revise your own wording.</p>${model.paragraphs.map(([name,text])=>`<div class="model-paragraph"><span class="tag">${esc(name)}</span><p>${esc(text)}</p></div>`).join('')}<h3>What to notice</h3><ul>${model.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`);break;}
case 'compare-writing':{const list=state.writingHistory.filter(h=>h.promptId===prompt().id);if(list.length<2){toast('Save a first draft and a revision of this same prompt to compare them.');break;}const first=list[0],last=list.at(-1);showModal('Your first draft and latest revision',`<div class="grid-even"><div><h3>First draft · ${wordCount(first.text)} words</h3><pre>${esc(first.text)}</pre></div><div><h3>Latest revision · ${wordCount(last.text)} words</h3><pre>${esc(last.text)}</pre></div></div><p class="text-small muted">Look for clearer ideas, better support and fewer recurring errors. Word count alone does not show improvement.</p>`);break;}
case 'save-speaking':{const note=state.speakingNotes[state.selectedCue]||'';if(note.trim().length<15){toast('Write one specific observation in your reflection first.');break;}ensureLearning(state).speaking.push({date:new Date().toISOString(),cue:state.selectedCue,note});const finished=finishLesson(state,lessons,'speaking',String(state.selectedCue));save();render();toast(finished?'Speaking reflection saved. Return to your lesson to continue.':'Speaking reflection saved.');break;}
case 'day':selectedDay=Number(b.dataset.day);render();break;
case 'timer-start':startTimer(b.dataset.kind,Number(b.dataset.seconds),b.dataset.label);break;
case 'timer-reset':if(state.timer?.kind===b.dataset.kind){state.timer={...state.timer,running:false,remaining:Number(b.dataset.seconds),end:0};save();render();}break;
case 'save-writing':{const p=prompt(),d=draft();if(!d.text.trim()){toast('Write an answer before saving a snapshot.');break;}state.writingHistory.push({id:uid(),promptId:p.id,text:d.text,checks:[...d.checks],date:new Date().toISOString()});const finished=wordCount(d.text)>=getWritingMinimum(p)&&finishLesson(state,lessons,'writing',p.id);save();render();toast(finished?'Attempt saved. Return to your lesson to continue.':'Snapshot saved. Revise it, then save another version.');break;}
case 'view-writing':{const h=state.writingHistory.find(x=>x.id===b.dataset.id);if(h)showModal('Saved draft',`<p class="text-small muted">${fmtDate(h.date)} · ${wordCount(h.text)} words</p><pre>${esc(h.text)}</pre>`);break;}
case 'copy-feedback':await copyText(feedbackText());break;
case 'download-writing':download(`ielts-${prompt().id}-${dateKey()}.txt`,feedbackText());break;
case 'speak-prep':startTimer('speaking-prep',60,'Part 2 preparation');break;
case 'speak-talk':startTimer('speaking-talk',120,'Part 2 speaking');break;
case 'next-cue':if(recording){toast('Stop recording before changing the question.');break;}state.selectedCue=(state.selectedCue+1)%cues.length;save();render();break;
case 'question-part':if(recording){toast('Stop recording before changing the question.');break;}ensureLearning(state).practice=null;questionPart=Number(b.dataset.part);questionIndex=0;save();render();break;
case 'next-question':if(recording){toast('Stop recording before changing the question.');break;}questionIndex++;render();break;
case 'record-start':await beginRecording();break;
case 'record-stop':if(recording?.state==='recording')recording.stop();break;
case 'audio-download':if(audioBlob)download(`ielts-speaking-card-${audioCue+1}-${dateKey()}.${audioBlob.type.includes('mp4')?'m4a':audioBlob.type.includes('ogg')?'ogg':'webm'}`,audioBlob);break;
case 'open-drill':openDrill(b.dataset.id);break;
case 'close-drill':if(!drillResult&&Object.keys(drillAnswers).length&&!confirm('Leave this unfinished drill? Your submitted results will stay saved.'))break;activeDrill=null;drillResult=null;render();break;
case 'delete-mock':if(confirm('Delete this practice result?')){state.mockAttempts=state.mockAttempts.filter(x=>x.id!==b.dataset.id);save();render();}break;
case 'reveal-mistake':reviewRevealed.add(b.dataset.id);render();break;
case 'review-good':case 'review-again':{const m=state.mistakes.find(x=>x.id===b.dataset.id);if(m){Object.assign(m,nextReview(m.level,a==='review-good'));reviewRevealed.delete(m.id);save();render();toast('Next review: '+fmtDate(m.due));}break;}
case 'delete-mistake':if(confirm('Delete this mistake card?')){state.mistakes=state.mistakes.filter(x=>x.id!==b.dataset.id);save();render();}break;
case 'video-filter':videoFilter=b.dataset.filter;render();break;
case 'export-recovery':if(recoveryRaw)download('ielts-original-recovery-'+dateKey()+'.json',recoveryRaw,'application/json');break;
case 'export-data':download(`band-seven-backup-${dateKey()}.json`,JSON.stringify(state,null,2),'application/json');toast('Backup exported. Keep your audio downloads separately.');break;
case 'backup-text':showModal('A portable copy of your progress',`<p class="text-small muted">If your browser cannot download files, copy this backup text and keep it in a note. To restore it later, paste the saved text below and choose Restore pasted backup. Restoring replaces this browser’s saved work.</p><label for="backup-text">Backup text</label><textarea id="backup-text" rows="10">${esc(JSON.stringify(state,null,2))}</textarea><div class="button-row" style="margin-top:15px">${button('copy-backup-text','Copy backup text')}${button('restore-backup-text','Restore pasted backup','outline')}</div>`);break;
case 'copy-backup-text':await copyText($('#backup-text').value);break;
case 'restore-backup-text':try{const imported=validateAppState(JSON.parse($('#backup-text').value));if(confirm(`Replace saved work with this backup? It contains ${imported.mockAttempts.length} mock results and ${Object.keys(imported.drafts).length} drafts.`)){imported.timer=null;clearTransient();writeBlocked=false;state=imported;selectedDay=dayNumber(state.settings.start);save();$('#modal').close();render();toast('Backup restored.');}}catch(err){toast('Restore failed: '+err.message);}break;
case 'choose-import':$('#import-file').click();break;
case 'download-summary':download(`ielts-progress-${dateKey()}.txt`,progressReport());break;
case 'reset-data':if(confirm('Reset all drafts, scores, notes and progress in this browser? Export a backup first if you want to keep them.')){clearTransient();writeBlocked=false;state=emptyState();selectedDay=1;save();render();toast('Saved work reset.');}break;
}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='writing-text'){draft().text=el.value;markDraftChanged();writingReport=null;$('#writing-report')?.remove();queueSave();$('#word-count').textContent=wordCount(el.value);const min=getWritingMinimum(prompt()),n=wordCount(el.value);$('#word-hint').textContent=n<min?`· ${min-n} below the minimum`:'· minimum reached';}if(el.closest('#drill-form')&&el.type==='text')drillAnswers[el.name]=el.value;if(el.id==='speaking-notes'){state.speakingNotes[state.selectedCue]=el.value;queueSave();}if(el.id==='speaking-answer'){speakingAnswer().text=el.value;queueSave();markDraftChanged();}if(el.id==='video-search'){videoSearch=el.value;const start=el.selectionStart;render();$('#video-search').focus();$('#video-search').setSelectionRange(start,start);}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='recording-upload'&&el.files?.[0]){const file=el.files[0];if(file.size>8000000){toast('Choose an audio file smaller than 8 MB.');return;}if(audioUrl)URL.revokeObjectURL(audioUrl);audioBlob=file;audioUrl=URL.createObjectURL(file);audioContext={...speakingContext(),cueIndex:state.selectedCue,duration:null};audioCue=state.selectedCue;if($('#recorder-area'))$('#recorder-area').innerHTML=recorderHtml();return;}if(el.dataset.task){state.tasks[el.dataset.task]=el.checked;save();render();}if(el.dataset.writingCheck!==undefined){draft().checks[Number(el.dataset.writingCheck)]=el.checked;save();}if(el.id==='prompt-select'){ensureLearning(state).practice=null;state.selectedPrompt=el.value;save();render();}if(el.id==='speaking-answer-mode'){speakingAnswer().mode=el.value;save();render();}if(el.id==='cue-select'){if(recording){el.value=String(state.selectedCue);toast('Stop recording before changing the question.');return;}state.selectedCue=Number(el.value);save();render();}if(el.dataset.video){const id=el.dataset.video;if(!state.videos[id])state.videos[id]={watched:false,practised:false};state.videos[id][el.dataset.status]=el.checked;save();render();}if(el.type==='radio'&&el.closest('#drill-form'))drillAnswers[el.name]=el.value;if(el.id==='import-file'&&el.files[0]){try{const file=el.files[0];if(file.size>10*1024*1024)throw Error('Please choose a backup smaller than 10 MB.');const imported=validateAppState(JSON.parse(await file.text()));if(confirm(`Replace this browser’s work with this backup? It contains ${imported.mockAttempts.length} mock results, ${Object.keys(imported.drafts).length} drafts and ${imported.mistakes.length} mistakes. Export your current work first if needed.`)){imported.timer=null;clearTransient();writeBlocked=false;state=imported;selectedDay=dayNumber(state.settings.start);save();render();toast('Backup imported. Running timers were cleared.');}}catch(err){toast('Import failed: '+err.message);}el.value='';}});
document.addEventListener('submit',e=>{if(!['mock-form','mistake-form','settings-form','drill-form','lesson-check-form'].includes(e.target.id))return;e.preventDefault();const f=e.target,fd=new FormData(f);if(f.id==='lesson-check-form'){const l=lessons.find(l=>l.id===f.dataset.lesson),r=lessonRecord(state,l.id);r.selected=Number(fd.get('lesson-answer'));r.submitted=true;r.correct=l.check.options[r.selected]===l.check.answer;save();render();return;}if(f.id==='mock-form'){try{const number=name=>fd.get(name)===''?null:Number(fd.get(name));const bands=[0,1,2,3].map(i=>number('band'+i)),provenance=fd.get('provenance');if((bands[2]!==null||bands[3]!==null)&&provenance==='unknown')throw Error('Label where your Writing/Speaking band came from, or leave it blank.');const a={id:uid(),source:fd.get('source').trim(),date:fd.get('date'),mode:fd.get('mode'),listening:number('listening'),reading:number('reading'),bands,provenance,created:Date.now()};if(!a.source)throw Error('Enter the test source and identifier.');if(a.listening===null&&a.reading===null&&bands.every(b=>b===null))throw Error('Enter at least one score.');const candidate={...state,mockAttempts:[...state.mockAttempts,a]};validateAppState(candidate);state=candidate;save();render();toast('Result saved with its attempt type.');}catch(err){$('#mock-error').textContent=err.message;}}
if(f.id==='mistake-form'){const problem=fd.get('problem').trim(),fix=fd.get('fix').trim(),tag=fd.get('tag').trim();if(!problem||!fix||!tag){toast('Add a question, correction and error type.');return;}addMistake({skill:fd.get('skill'),tag,problem,fix});save();render();toast('Added to tomorrow’s review.');}
if(f.id==='settings-form'){try{const settings={start:fd.get('start'),exam:fd.get('exam'),hours:Number(fd.get('hours')),minimum:fd.get('minimum')===''?null:Number(fd.get('minimum'))};if(settings.exam<settings.start)throw Error('Your test date must be on or after your preparation start.');validateAppState({...state,settings});state.settings=settings;selectedDay=dayNumber(settings.start);save();render();toast('Study settings saved.');}catch(err){$('#settings-error').textContent=err.message;}}
if(f.id==='drill-form'){const d=activeDrill;if(d.questions.some(q=>fd.get(q.id)===null||String(fd.get(q.id)).trim()==='')){toast('Answer every question before checking.');return;}const answers=d.questions.map(q=>q.type==='text'?String(fd.get(q.id)).trim():q.options[Number(fd.get(q.id))]);const marked=markDrill(d,answers),first=!state.drillAttempts.some(a=>a.drillId===d.id);state.drillAttempts.push({id:uid(),drillId:d.id,date:new Date().toISOString(),correct:marked.correct,total:d.questions.length,answers,first,plays:d.audio?drillPlays:0,elapsed:Math.round((Date.now()-drillStarted)/1000)});d.questions.forEach((q,i)=>{if(!marked.results[i].correct)addMistake({origin:q.id,skill:d.skill,tag:q.tag,problem:q.question,fix:`Correct answer: ${q.answer}\n${q.explanation}\nYour earlier answer: ${answers[i]}`});});drillResult={...marked,answers,first,wrong:marked.correct<d.questions.length};finishLesson(state,lessons,'drill',d.id);if(state.timer?.kind==='drill-'+d.id){state.timer.remaining=secondsLeft(state.timer);state.timer.running=false;}save();render();window.scrollTo(0,0);}});
document.addEventListener('play',e=>{if(e.target.id==='drill-audio')drillPlays++;},true);
function clearTransient(){recordRequestId++;recordingPending=false;cancelGrading();graderConnected=false;audioContext=null;clearTimeout(recordingTimeout);ensureLearning(state).practice=null;writingReport=null;activeDrill=null;drillAnswers={};drillResult=null;reviewRevealed.clear();if(recording){recording.onstop=null;if(recording.state==='recording')recording.stop();recording.stream.getTracks().forEach(t=>t.stop());recording=null;}if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;audioBlob=null;audioCue=null;}
function progressReport(){return `IELTS Academic — progress report\nGenerated ${dateKey()}\nTarget: 9 in every skill${state.settings.minimum?`, minimum ${state.settings.minimum} per section`:''}\n\nMOCK RESULTS\n${state.mockAttempts.map(a=>`${a.date} | ${a.source} | ${a.mode} | L ${a.listening??'?'}/40, R ${a.reading??'?'}/40 | bands L/R/W/S ${a.bands.map(b=>b??'?').join('/')} | W/S ${a.provenance}`).join('\n')}\n\nDRILLS (item accuracy only, not IELTS bands)\n${state.drillAttempts.map(a=>`${a.date} | ${a.drillId} | ${a.correct}/${a.total} | ${a.first?'first attempt':'repeat'}`).join('\n')}\n\nMISTAKES TO WORK ON\n${state.mistakes.map(m=>`${m.skill}: ${m.problem}\nCorrection: ${m.fix}\nReview: ${m.due}`).join('\n\n')}\n\nWriting snapshots: ${state.writingHistory.length}\nVideos with follow-up exercise completed: ${Object.values(state.videos).filter(v=>v.practised).length}\n\nPractice feedback and self/AI assessments are provisional, not official results. Gemini feedback estimates a Writing task or an audible recorded sample; a full Writing result combines both tasks and a full Speaking result requires the complete test. Talking points and transcripts do not establish an overall Speaking band. Browser backups preserve local work; download recordings separately.`;}
window.addEventListener('hashchange',()=>{if(route==='speaking'&&location.hash!=='#speaking'){recordRequestId++;recordingPending=false;}if(route==='speaking'&&location.hash!=='#speaking'&&recording?.state==='recording')recording.stop();render();window.scrollTo(0,0);});window.addEventListener('pagehide',()=>{save();recordRequestId++;recordingPending=false;if(recording?.state==='recording')recording.stop();});$('#global-timer').addEventListener('click',()=>{if(!state.timer)return;const kind=state.timer.kind;let destination='drills';if(kind.startsWith('writing-')){state.selectedPrompt=kind.slice(8);destination='writing';save();}else if(kind.startsWith('speaking'))destination='speaking';else if(kind.startsWith('drill-')){const id=kind.slice(6);if(activeDrill?.id!==id){activeDrill=drills.find(d=>d.id===id)||null;drillAnswers={};drillResult=null;drillStarted=Date.now();}}if(location.hash==='#'+destination)render();else location.hash=destination;});
studio=createAssessmentStudio({getState:()=>state,storageAvailable:()=>storageAvailable,esc,head,button,link,connected:()=>graderConnected,job:()=>gradeJob,error:()=>gradeError,prompt,draft,minimum:getWritingMinimum,timerControls,prompts,cues,speakingContext,speakingAnswer,recorderHtml});
learningUI=createLearningUI({getState:()=>state,getDrills:()=>drills,getVideos:()=>videos,getFilter:()=>courseFilter,esc,head,button,link,lessons});
try{const [videoData,base,extra,listening]=await Promise.all(['videos.json','drills.json','reading-extra.json','listening.json'].map(file=>fetch('./'+file+'?v=20261015').then(r=>{if(!r.ok)throw Error('Practice library unavailable');return r.json();})));videos=videoData;drills=[...base,...extra,...listening];ensureAssessments(state);render();setInterval(updateTimer,500);}catch(err){$('#main').innerHTML=empty('The practice library could not load','Check your connection and reload this page. Your saved work stays in this browser.');console.error(err);}
